   "codice": "extends RefCounted


func run() -> float:
	var margin: float = 4.0
	var spacing: float = 2.0
	var tile_size: float = 16.0
	var column: int = 2
	var x_pos: float = margin + column * (tile_size + spacing)
	return x_pos
",
   "domanda": "Quanto vale `x_pos` alla fine?",
   "spiegazione": "Si parte dal margine iniziale di 4. La colonna 2 salta 2 celle complete più i relativi spazi: `2 * (16 + 2) = 36`. Aggiungendo il margine iniziale si ottiene 40."
