   "codice": "extends RefCounted


func run() -> Vector2i:
	var frame_index: int = 5
	var hframes: int = 4
	var col: int = frame_index % hframes
	var row: int = frame_index / hframes
	return Vector2i(col, row)
",
   "domanda": "Che Vector2i restituisce `run()`?",
   "spiegazione": "L'indice 5 in una griglia con 4 colonne (`hframes = 4`) si trova alla colonna `5 % 4 = 1` e alla riga `5 / 4 = 1` (divisione intera tra interi)."
